def resolveCommand(entrypoint, cmd, run_args, entrypoint_override):
    def norm(v):
        if v is None:
            return []
        if isinstance(v, str):
            return ["/bin/sh", "-c", v]
        return list(v)

    shell_entry = False
    if entrypoint_override is not None:
        ep = [entrypoint_override]
        cmd = None
    else:
        ep = norm(entrypoint)
        shell_entry = isinstance(entrypoint, str)
    if shell_entry:
        return ep
    tail = list(run_args) if run_args else norm(cmd)
    return ep + tail

