def reorderSteps(steps, builds):
    n = len(steps)
    if n == 0:
        return []
    idx = {s[0]: i for i, s in enumerate(steps)}
    cost = [s[1] for s in steps]
    need = [0] * n
    for i, s in enumerate(steps):
        for d in s[2]:
            need[i] |= 1 << idx[d]
    bmasks = []
    for b in builds:
        m = 0
        for sid in b:
            m |= 1 << idx[sid]
        if m:
            bmasks.append(m)
    full = (1 << n) - 1
    INF = float("inf")
    dp = [INF] * (full + 1)
    choice = [-1] * (full + 1)
    dp[0] = 0
    for mask in range(1, full + 1):
        hit = sum(1 for m in bmasks if m & mask)
        for i in range(n):
            bit = 1 << i
            if mask & bit:
                prev = mask ^ bit
                if dp[prev] < INF and (need[i] & prev) == need[i]:
                    c = dp[prev] + cost[i] * hit
                    if c < dp[mask]:
                        dp[mask] = c
                        choice[mask] = i
    order, mask = [], full
    while mask:
        i = choice[mask]
        order.append(steps[i][0])
        mask ^= 1 << i
    return order[::-1]

