def diskUsage(images):
    size, users = {}, {}
    virtual = 0
    for layers in images.values():
        seen = set()
        for lid, sz in layers:
            if lid in seen:
                continue
            seen.add(lid)
            size[lid] = sz
            users[lid] = users.get(lid, 0) + 1
            virtual += sz
    actual = sum(size.values())
    shared = sum(size[l] for l in size if users[l] >= 2)
    return [virtual, actual, shared]

