def unionLookup(layers, paths):
    def lookup(path):
        parts = path.split("/")
        ancestors = ["/".join(parts[:i]) for i in range(2, len(parts))]
        for layer in reversed(layers):
            if path in layer:
                return layer[path]
            for a in ancestors:
                if a in layer and layer[a] is None:
                    return None
        return None
    return [lookup(p) for p in paths]

