def stagesNeeded(stages, target):
    if not stages:
        return []
    index = {s[0]: i for i, s in enumerate(stages)}
    if target == "":
        target = stages[-1][0]
    if target not in index:
        return []
    needed = set()
    stack = [index[target]]
    while stack:
        i = stack.pop()
        if i in needed:
            continue
        needed.add(i)
        _, base, copies = stages[i]
        for ref in [base] + list(copies):
            j = index.get(ref)
            if j is not None and j < i:
                stack.append(j)
    return [stages[i][0] for i in sorted(needed)]

docker-rolling-update.solution:
def rollingUpdate(replicas, parallelism, failing, failure_action):
    states = ["old"] * replicas
    bad = set(failing)
    step = parallelism if parallelism > 0 else max(replicas, 1)
    batches = 0
    for start in range(0, replicas, step):
        batches += 1
        failed = False
        for i in range(start, min(start + step, replicas)):
            if (i + 1) in bad:
                states[i] = "failed"
                failed = True
            else:
                states[i] = "new"
        if failed:
            if failure_action == "pause":
                return [states, "paused", batches]
            if failure_action == "rollback":
                return [["old"] * replicas, "rolled_back", batches]
    return [states, "completed", batches]

