def rotateLogs(line_sizes, max_size, max_file):
    files, lost = [0], 0
    counts = [0]
    for size in line_sizes:
        if counts[0] > 0 and files[0] + size > max_size:
            files.insert(0, 0)
            counts.insert(0, 0)
            while len(files) > max_file:
                lost += files.pop()
                counts.pop()
        files[0] += size
        counts[0] += 1
    return [files, lost]
